/**
 * Sandbox.
 *
 * Real CRM data goes in; nothing comes back out. Every action that would write —
 * creating a tranche, locking it, generating documents, adding a pricing row — runs here
 * against local state instead, so the flow behaves like the finished tool while CRM stays
 * untouched.
 *
 * This is not a stub that pops a "not implemented" dialog. Gabe reviews by using the
 * thing, so a created tranche has to actually appear in Recent, its deals actually have
 * to leave the pool, and locking actually has to flip the status and list the documents.
 * The only lie is that none of it reaches Zoho.
 *
 * State survives a reload (localStorage) so a review session isn't lost to a refresh, and
 * `reset()` puts it back to untouched.
 */

const KEY = 'maxwell-tranche-sandbox-v1';

const blank = () => ({
  tranches: [],   // sandbox-created tranches (local only)
  pricing: {},    // investorId -> pricing rows (see pricing.js)
  liveCreated: [], // tranches actually written to CRM this session, for one-click undo
  crmRates: {},   // "accountId|State|Product" -> { column: value } — local preview of CRM cells
  seq: 0,
});

function load() {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return blank();
    const parsed = JSON.parse(raw);
    return { ...blank(), ...parsed };
  } catch {
    // Corrupt or unavailable storage must never stop the widget rendering.
    return blank();
  }
}

export const sandbox = load();

function persist() {
  try {
    localStorage.setItem(KEY, JSON.stringify(sandbox));
  } catch {
    // Private browsing / quota. Losing persistence is acceptable; crashing is not.
  }
}

export function reset() {
  const fresh = blank();
  sandbox.tranches = fresh.tranches;
  sandbox.pricing = fresh.pricing;
  sandbox.liveCreated = fresh.liveCreated;
  sandbox.crmRates = fresh.crmRates;
  sandbox.seq = fresh.seq;
  persist();
}

/* ---- local swap (for sandbox-created tranches; the CRM swap lives in zoho.js) ---- */

/** Swap one deal out of a local sandbox tranche and one in. Mutates its deal list in place. */
export function swapTranche(trancheId, outDealId, inDealId) {
  const t = sandbox.tranches.find((x) => x.id === trancheId);
  if (!t) return null;
  t.dealIds = t.dealIds.filter((id) => String(id) !== String(outDealId));
  if (inDealId && !t.dealIds.includes(String(inDealId))) t.dealIds.push(String(inDealId));
  t.swaps = t.swaps ?? [];
  t.swaps.push({ out: String(outDealId), in: inDealId ? String(inDealId) : null, at: new Date().toISOString() });
  persist();
  return t;
}

/* ---- local preview of CRM pricing cells (standalone browser, no live SDK) ---- */

const rk = (accountId, state, product) => `${accountId}|${state}|${product}`;

export function getCrmRate(accountId, state, product) {
  return sandbox.crmRates[rk(accountId, state, product)] ?? {};
}

export function setCrmRate(accountId, state, product, column, value) {
  const k = rk(accountId, state, product);
  sandbox.crmRates[k] = { ...(sandbox.crmRates[k] ?? {}), [column]: value };
  persist();
  return sandbox.crmRates[k];
}

/** Every locally-previewed cell for an investor, as flat rows. */
export function crmRatesFor(accountId) {
  const out = [];
  for (const [k, cells] of Object.entries(sandbox.crmRates)) {
    const [acc, state, product] = k.split('|');
    if (acc !== String(accountId)) continue;
    for (const [column, value] of Object.entries(cells)) out.push({ state, product, column, value });
  }
  return out;
}

/* ---- CRM-created tranches (for undo) ---- */

export function recordLiveCreate(rec) {
  sandbox.liveCreated = sandbox.liveCreated ?? [];
  sandbox.liveCreated.unshift(rec); // { trancheId, name, dealIds, investorName, createdAt }
  persist();
}

/** Match a CRM tranche id to a session-created record, so we only offer undo on our own. */
export function liveCreatedFor(trancheId) {
  return (sandbox.liveCreated ?? []).find((r) => String(r.trancheId) === String(trancheId)) ?? null;
}

export function forgetLiveCreate(trancheId) {
  sandbox.liveCreated = (sandbox.liveCreated ?? []).filter((r) => String(r.trancheId) !== String(trancheId));
  persist();
}

/** After a live swap, keep our tracked deal list for the tranche in sync (out removed, in added). */
export function applyLiveSwap(trancheId, outId, inId) {
  const rec = liveCreatedFor(trancheId);
  if (!rec) return;
  rec.dealIds = (rec.dealIds ?? []).filter((id) => String(id) !== String(outId));
  if (inId && !rec.dealIds.includes(String(inId))) rec.dealIds.push(String(inId));
  persist();
}

/** Deals held by any sandbox tranche — they should disappear from the pools, as they would in CRM. */
export function committedDealIds() {
  const ids = new Set();
  for (const t of sandbox.tranches) for (const id of t.dealIds) ids.add(String(id));
  return ids;
}

/**
 * Create a tranche.
 *
 * Name follows `automation.Untitled_Function2` — "<Investor Account_Name> Tranche
 * <Tranche_Date>" — because downstream CRM report filters depend on that exact shape, and
 * a demo that shows a different name teaches the wrong thing.
 *
 * Status starts "Open", matching the real Tranche_Status picklist
 * {Open, Locked, Funded, Complete}. The mockup's "Draft" is the pre-save working state in
 * the widget, not a CRM value.
 */
export function createTranche({ investor, dealIds, totals, adders, targetLock }) {
  sandbox.seq += 1;
  const t = {
    id: `SBX-${String(sandbox.seq).padStart(3, '0')}`,
    name: `${investor.Account_Name} Tranche ${targetLock}`,
    investorId: investor.id,
    investorName: investor.Account_Name,
    dealIds: dealIds.map(String),
    totals,
    adders: adders.map((a) => ({ ...a })),
    status: 'Open',
    createdAt: new Date().toISOString(),
    lockedAt: null,
    documents: [],
  };
  sandbox.tranches.unshift(t);
  persist();
  return t;
}

/**
 * The documents `button.send_tranche_envelope` would raise. Template ids are the real ones
 * so the preview matches what actually fires when this is wired up.
 */
const DOCUMENTS = [
  { name: 'BOS and A&AA', template: '154758000019030075', via: 'Zoho Sign' },
  { name: 'Tranche Schedule PDF', template: 'Creator print template', via: 'Creator' },
];

export function lockTranche(id) {
  const t = sandbox.tranches.find((x) => x.id === id);
  if (!t) return null;
  t.status = 'Locked';
  t.lockedAt = new Date().toISOString();
  t.documents = DOCUMENTS.map((d) => ({
    ...d,
    generatedAt: t.lockedAt,
    status: 'Sent for signature',
  }));
  persist();
  return t;
}

export function deleteTranche(id) {
  const i = sandbox.tranches.findIndex((x) => x.id === id);
  if (i >= 0) {
    sandbox.tranches.splice(i, 1);
    persist();
  }
}

/* ------------------------------------------------------------------ pricing */

export function getPricing(investorId) {
  return sandbox.pricing[investorId] ?? null;
}

export function setPricing(investorId, rows) {
  sandbox.pricing[investorId] = rows;
  persist();
}

export function addPricingRow(investorId, row) {
  const rows = sandbox.pricing[investorId] ?? [];
  rows.push(row);
  sandbox.pricing[investorId] = rows;
  persist();
  return row;
}

/** Everything the sandbox is currently holding — shown in the UI so it never feels like real state. */
export function summary() {
  return {
    tranches: sandbox.tranches.length,
    locked: sandbox.tranches.filter((t) => t.status === 'Locked').length,
    dealsCommitted: committedDealIds().size,
    investorsPriced: Object.keys(sandbox.pricing).length,
  };
}
