import './styles.css';
import { priceDeal, trancheTotals, tagsFor, taxCreditFor, allocate, num, round2, isEC } from './calc.js';
import {
  POOLS, poolFor, hasFinal, loadDeals, loadInvestors, loadPoolViews,
  loadRecentTranches, priceFor, priceGapFor, pricingGaps, SOURCE, isLive, fallback,
  POOL_QUERIES, poolCounts, canSubdivide, mode, poolCriteria, ensureInvestorPricing,
  ensureAllInvestorPricing,
} from './data.js';
import { COLUMNS as CRM_RATE_COLUMNS, columnForRubric, productFor, PRODUCTS } from './livePricing.js';
import { roleForUser, viewAsOptions, can, denyReason, CAPS, ROLES } from './roles.js';
import * as sandbox from './sandbox.js';
import { matrixFor, lookup, addRate, saveMatrix, rubricFor, DEFAULT_FEES, TAX_TIERS, fmtPct, loadStarterRates, matrixStatus } from './pricing.js';
import { explainDeal, explainTranche, explainAction } from './explain.js';
import { ASSUMPTIONS, openQuestions } from './assumptions.js';
import { whenReady, currentUser, orgInfo, inZoho, WRITES_ENABLED, TRANCHE_CREATE_WRITES, TRANCHE_SWAP_WRITES, PRICING_WRITES, TEST_INVESTOR_IDS, createTrancheLive as zohoCreateTrancheLive, undoTrancheLive as zohoUndoTrancheLive, swapTrancheLive as zohoSwapTrancheLive, saveInvestorRateLive as zohoSaveInvestorRateLive } from './zoho.js';
import { diag, note, summary } from './diag.js';

/**
 * Injected by Vite at build time (see vite.config.js). Rendered at the top of the widget
 * so "has the new build loaded in Zoho?" is answerable at a glance — both Zoho and
 * GitHub Pages cache hard enough that it is a real question on every deploy.
 */
const BUILD = typeof __BUILD__ !== 'undefined' ? __BUILD__ : { version: 'dev', sha: 'local', built: '—' };

/* ------------------------------------------------------------------ utils */
const $ = (s, r = document) => r.querySelector(s);
const el = (t, c, txt) => { const n = document.createElement(t); if (c) n.className = c; if (txt != null) n.textContent = txt; return n; };
const money = (n) => n == null ? '—' : n.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
const moneyK = (n) => n == null ? '—' : Math.abs(n) >= 1000 ? '$' + Math.round(n / 1000).toLocaleString() + 'K' : money(n);
const pct = (n) => n == null ? '—' : (n * 100).toFixed(1) + '%';
const initials = (s) => String(s || '?').split(/\s+/).slice(0, 2).map((w) => w[0]).join('').toUpperCase();

/* ------------------------------------------------------------------ state */
const S = {
  deals: [], investors: [], recent: [], poolViews: [],
  investorId: null,
  pool: 'available',
  picked: new Set(),
  stateFilter: new Set(),
  realUser: null, realRole: ROLES.observer,
  viewAs: null,          // null ⇒ acting as the real user
  adders: [
    // The financing fee is now a real per-deal value (Commitment_Fee) inside Bill of Sale,
    // so it's no longer a tranche-level adder. Tax insurance stays; add others with "+".
    { label: 'Tax insurance', amount: 0, fixed: true },
  ],
  targetLock: new Date(Date.now() + 3 * 864e5).toISOString().slice(0, 10),
  // Gabe: "filter down to mctesty deals only, like dealname.contains mctesty, so we have a
  // controlled pop of deals." Sandbox defaults to his curated set; live starts unfiltered.
  nameFilter: mode.isSandbox && isLive() ? 'mctesty' : '',
};

/**
 * The role the signed-in user acts as when NOT simulating someone else.
 *
 * In the sandbox this is Investor Admin regardless of who's logged in — it's a safe
 * playground (test deals, guarded writes), and the real demo users (Trevor, Gabe) aren't
 * in the named IR list, so mapping them to Observer would lock them out of the very thing
 * they're here to try. "View as" still lets them preview Coordinator/Observer restrictions.
 * In live mode it's their real mapped role — moot anyway, since live is read-only.
 */
const selfRole = () => (mode.isSandbox ? ROLES.investor_admin : S.realRole);
const actingUser = () => S.viewAs ?? { name: S.realUser?.full_name ?? 'Unknown user', email: S.realUser?.email ?? null, role: selfRole() };
const actingRole = () => actingUser().role;
const investor = () => S.investors.find((i) => i.id === S.investorId) ?? null;

/* ------------------------------------------------------------------ derive */
function dealsInPool(key) {
  // Deals held by a sandbox tranche leave the pool, exactly as a real CRM tranche
  // assignment would remove them. Without this, creating a tranche changes nothing
  // visible and the demo falls flat.
  const committed = sandbox.committedDealIds();
  // The deal-name filter (default "mctesty" in sandbox) narrows to a controlled set.
  const nf = (S.nameFilter || '').trim().toLowerCase();
  return S.deals.filter(
    (d) =>
      poolFor(d) === key &&
      !committed.has(String(d.id)) &&
      // A deal added to the working tranche leaves the pool and shows up in "In this
      // tranche" — removing it there returns it here. They move in and out.
      !S.picked.has(d.id) &&
      (!nf || String(d.Deal_Name || '').toLowerCase().includes(nf))
  );
}

function visibleDeals() {
  let list = dealsInPool(S.pool);
  if (S.stateFilter.size) list = list.filter((d) => S.stateFilter.has(d.Customer_State));
  return list;
}

function priced(deal) {
  const inv = investor();
  const row = inv ? priceFor(deal, inv) : null;
  // A priced deal uses the investor's bill-of-sale percentage: BoS = prepay / BoS%.
  // Unpriced falls back to CRM's own computed Bill_of_Sale_Amount so the row still shows
  // real economics while the gap is flagged.
  const calc = priceDeal(deal, { bosPct: row ? row.bosPct : null });
  return { deal, calc, eligible: !!row, pricing: row, gap: row ? null : priceGapFor(deal, inv) };
}

const pickedRows = () => [...S.picked].map((id) => {
  const d = S.deals.find((x) => x.id === id);
  return d ? priced(d) : null;
}).filter(Boolean);

/* ------------------------------------------------------------------ render */
function render() {
  renderSandbox();
  renderModeSwitch();
  renderWho();
  renderHead();
  renderPools();
  renderPoolTable();
  renderSummary();
  renderAdders();
  renderWorking();
  renderActions();
  renderRecent();
}

function renderSandbox() {
  const box = $('#sbx');
  box.innerHTML = '';
  box.classList.toggle('is-live', !mode.isSandbox);

  if (!mode.isSandbox) {
    // Live mode: read-only. The mode switch note already explains it; keep this quiet.
    box.append(el('span', '', 'Live mode — viewing real deals, read-only. Nothing here changes CRM.'));
    return;
  }

  const s = sandbox.summary();
  const left = el('div');
  left.append(el('strong', '', 'Sandbox — nothing is written to CRM. '));
  left.append(
    el('span', '', s.tranches
      ? `${s.tranches} tranche${s.tranches > 1 ? 's' : ''} created (${s.locked} locked), ${s.dealsCommitted} deals committed, ${s.investorsPriced} investor${s.investorsPriced === 1 ? '' : 's'} priced.`
      : 'Create, lock and price freely — it all stays in this browser.')
  );
  box.append(left);
  const btn = el('button', 'mini', 'Reset sandbox');
  // Bound here, not in boot(): renderSandbox() rebuilds this node on every render, so a
  // one-time boot binding would be attached to an element that no longer exists.
  btn.onclick = () => {
    sandbox.reset();
    S.picked.clear();
    S.activeTranche = null;
    render();
  };
  box.append(btn);
}

function renderWho() {
  const u = actingUser();
  const role = u.role;
  const simulating = !!S.viewAs;

  const box = $('#who');
  box.innerHTML = '';

  const left = el('div', 'who-l');
  left.append(el('div', 'avatar', initials(u.name)));
  const idBlock = el('div');
  idBlock.append(el('div', 'who-name', u.name));
  const sub = el('div', 'who-sub');
  sub.textContent = u.email ?? (S.viewAs ? 'simulated role' : 'no email on record');
  if (simulating) sub.textContent += `  ·  simulated (really signed in as ${S.realUser?.full_name ?? 'unknown'})`;
  idBlock.append(sub);
  left.append(idBlock);
  const pill = el('span', `role-pill ${role.key === 'investor_coordinator' ? 'coordinator' : role.key === 'observer' ? 'observer' : ''}`, role.label);
  pill.title = role.blurb;
  left.append(pill);

  const ver = el('span', 'build', `v${BUILD.version}`);
  ver.title = `build ${BUILD.sha} · ${BUILD.built}`;
  left.append(ver);

  const right = el('div', 'who-r');
  right.append(el('label', '', 'View as'));
  const sel = el('select');
  sel.id = 'viewAs';
  const meOpt = el('option', '', `Me — ${S.realUser?.full_name ?? 'signed-in user'}`);
  meOpt.value = '';
  sel.append(meOpt);
  for (const o of viewAsOptions()) {
    const opt = el('option', '', `${o.name} · ${o.role.label}`);
    opt.value = o.id;
    if (S.viewAs?.id === o.id) opt.selected = true;
    sel.append(opt);
  }
  sel.onchange = (e) => {
    S.viewAs = e.target.value ? viewAsOptions().find((o) => o.id === e.target.value) : null;
    render();
  };
  right.append(sel);

  box.append(left, right);

  const caps = el('div', 'caps');
  for (const [cap, label] of [
    [CAPS.BUILD, 'Build tranche'], [CAPS.LOCK, 'Lock + documents'],
    [CAPS.SWAP, 'Swap deals'], [CAPS.PRICING, 'Edit pricing'], [CAPS.REPORT, 'Reporting'],
  ]) {
    caps.append(el('span', `cap ${can(role, cap) ? '' : 'off'}`, label));
  }
  box.append(caps);
}

function renderHead() {
  const inv = investor();
  const sel = $('#investor');
  sel.innerHTML = '';
  for (const i of S.investors) {
    const o = el('option', '', i.Account_Name + (i.real ? '' : '  [sample]'));
    o.value = i.id;
    if (i.id === S.investorId) o.selected = true;
    sel.append(o);
  }
  $('#targetLock').textContent = S.targetLock;
  $('#invNote').textContent = inv?.note ?? '';
}

/** Are the create/lock/price/swap actions available? Only in sandbox mode. */
const actionsOn = () => mode.isSandbox;
/** An action is permitted only when the role allows it AND we're in sandbox mode. */
const may = (role, cap) => actionsOn() && can(role, cap);
/** Why an action is blocked — live-mode message wins, since it applies to everyone. */
const whyBlocked = (role, cap) =>
  !actionsOn() ? 'Live mode is read-only — switch to Sandbox to make changes'
  : (denyReason(role, cap) || '');

/**
 * The Sandbox ⇄ Live switch. One control sets both what you see and what you can touch:
 *   Sandbox = test deals, everything interactive (Gabe plays).
 *   Live    = real deals, read-only (the team looks).
 */
function renderModeSwitch() {
  const box = $('#testFilter');
  if (!box) return;
  box.innerHTML = '';

  const swap = async (v) => {
    if (mode.value === v) return;
    mode.set(v);
    // Sandbox defaults to Gabe's mctesty set; live starts unfiltered.
    S.nameFilter = v === 'sandbox' && isLive() ? 'mctesty' : '';
    S.deals = await loadDeals();
    S.picked.clear();
    render();
  };

  const seg = el('div', 'modeswitch');
  const sb = el('button', `mode-opt ${mode.isSandbox ? 'active sandbox' : ''}`, 'Sandbox');
  sb.title = 'Test deals only · every action works · nothing touches CRM';
  sb.onclick = () => swap('sandbox');
  const lv = el('button', `mode-opt ${!mode.isSandbox ? 'active live' : ''}`, 'Live');
  lv.title = 'Real deals · read-only · look but don\'t touch';
  lv.onclick = () => swap('live');
  seg.append(sb, lv);
  box.append(seg);

  // Deal-name filter — a controlled population, Gabe's "dealname.contains mctesty".
  const nameWrap = el('label', 'namefilter');
  nameWrap.append(el('span', '', 'Name contains'));
  const inp = el('input');
  inp.type = 'search';
  inp.placeholder = 'e.g. mctesty';
  inp.value = S.nameFilter;
  inp.oninput = (e) => { S.nameFilter = e.target.value; render(); }; // client-side, instant
  nameWrap.append(inp);
  box.append(nameWrap);

  const note = el('span', 'mode-note');
  const nf = (S.nameFilter || '').trim();
  note.textContent = mode.isSandbox
    ? `Sandbox — test deals${nf ? ` named “${nf}”` : ''}. Create, lock and pricing all work here; nothing is written to CRM.`
    : `Live — real deals${nf ? ` named “${nf}”` : ''}, read-only. Actions are turned off.`;
  note.classList.add(mode.isSandbox ? 'sandbox' : 'live');
  box.append(note);
}

function renderPools() {
  const bar = $('#pools');
  bar.innerHTML = '';
  bar.append(el('span', 'lbl', 'Pool:'));
  for (const p of POOLS) {
    const n = dealsInPool(p.key).length;
    const b = el('button', `pool ${S.pool === p.key ? 'active' : ''}`, `${p.label} · ${n}`);
    // Hover shows the full criteria; clicking also pins it in the panel below.
    b.title = `${p.label}\n\nCriteria:\n• ${(p.criteria ?? [p.hint]).join('\n• ')}`;
    b.onclick = () => { S.pool = p.key; render(); };
    bar.append(b);
  }
  renderCriteria();
}

/**
 * The active pool's full criteria, always visible under the tabs — the "show me what these
 * jobs are" ask. Plain-English rules, the exact live COQL, the confidence, and what the
 * pool actually returned last fetch (so a 0 is explainable, not mysterious).
 */
function renderCriteria() {
  const box = $('#criteria');
  if (!box) return;
  const c = poolCriteria(S.pool);
  box.innerHTML = '';

  const head = el('div', 'crit-head');
  head.append(el('span', 'crit-title', c.label));
  const count = el('span', 'crit-count');
  if (c.countError) count.textContent = `query failed`;
  else if (c.count !== null) count.textContent = `${c.count} in CRM${mode.isSandbox ? ' (test only)' : ''}`;
  else count.textContent = c.live ? '' : 'sample data';
  head.append(count);
  box.append(head);

  const list = el('ul', 'crit-list');
  for (const rule of c.criteria) list.append(el('li', '', rule));
  box.append(list);

  if (c.coql && c.live) {
    const coql = el('div', 'crit-coql');
    coql.append(el('span', 'crit-coql-lbl', 'Live filter'));
    coql.append(el('code', '', `WHERE ${c.coql}`));
    box.append(coql);
  }
  if (c.confidence) {
    const conf = el('div', 'crit-conf');
    conf.textContent = c.confidence;
    conf.classList.add(/verified/i.test(c.confidence) ? 'verified' : 'provisional');
    box.append(conf);
  }
}

function renderPoolTable() {
  const pool = POOLS.find((p) => p.key === S.pool);
  const all = dealsInPool(S.pool);
  const list = visibleDeals();

  const states = [...new Set(all.map((d) => d.Customer_State))].sort();
  const fbox = $('#filters');
  fbox.innerHTML = '';
  for (const st of states) {
    const on = S.stateFilter.has(st);
    const b = el('button', `pool ${on ? 'active' : ''}`, st);
    b.onclick = () => { on ? S.stateFilter.delete(st) : S.stateFilter.add(st); render(); };
    fbox.append(b);
  }
  $('#shown').textContent = `${list.length} of ${all.length} shown`;

  const body = $('#poolBody');
  body.innerHTML = '';

  // Only subdivide when the data can actually answer "has a final". On live records no
  // field is confirmed to mean that, and splitting anyway would label every deal wrongly.
  const groups =
    pool.subdivide && canSubdivide(list)
      ? [
          { label: 'Has a final', items: list.filter(hasFinal) },
          { label: 'No final yet', items: list.filter((d) => !hasFinal(d)) },
        ]
      : [{ label: null, items: list }];

  let rendered = 0;
  for (const g of groups) {
    if (!g.items.length) continue;
    if (g.label) {
      const tr = el('tr');
      const td = el('td', 'grouphdr', g.label);
      td.colSpan = 5;
      tr.append(td);
      body.append(tr);
    }
    for (const d of g.items.slice(0, 60)) { body.append(dealRow(d)); rendered += 1; }
  }
  if (!rendered) {
    const tr = el('tr');
    const td = el('td', 'empty', 'No deals match this pool and filter.');
    td.colSpan = 5;
    tr.append(td);
    body.append(tr);
  }
  const more = list.length - Math.min(list.length, 60);
  $('#poolFoot').textContent = more > 0 ? `+ ${more} more deals in pool` : '';
  $('#poolFoot').hidden = more <= 0;
}

function dealRow(d) {
  const p = priced(d);
  const inTranche = S.picked.has(d.id);
  const role = actingRole();
  const mayBuild = may(role, CAPS.BUILD);

  const tr = el('tr');

  const c1 = el('td');
  c1.append(el('div', 'dname', d.Deal_Name));
  c1.append(el('div', 'dsub', `${d.Account_Name ?? '—'} · ${d.Deal_Type ?? ''}`));
  tr.append(c1);

  tr.append(el('td', '', d.Customer_State ?? '—'));

  const c3 = el('td');
  for (const t of tagsFor(d)) {
    const s = el('span', `tag ${t.key}`, t.label);
    s.title = t.title;
    c3.append(s);
  }
  tr.append(c3);

  const c4 = el('td', 'r');
  if (p.eligible) {
    const bosLine = el('div', 'bos-line', money(p.calc.bos));
    bosLine.style.cursor = 'pointer';
    bosLine.title = 'Click to see the math';
    bosLine.onclick = () => dealMathModal(d, p);
    c4.append(bosLine);
    c4.append(el('div', 'dsub', `IC ${money(p.calc.investorContribution)}`));
  } else {
    // Name the rubric that is unpriced rather than a vague "not eligible" — this is the
    // whole point of the lookup: "If the pricing is not there, it tells you it's not there."
    c4.append(el('div', 'blocked', 'No pricing'));
    c4.append(el('div', 'dsub', p.gap?.reason ?? 'Rubric not priced'));
  }
  tr.append(c4);

  const c5 = el('td', 'c');
  if (p.eligible) {
    const b = el('button', `mini ${inTranche ? 'in' : ''}`, inTranche ? '✓' : 'Add');
    b.disabled = !mayBuild;
    if (!mayBuild) b.title = whyBlocked(role, CAPS.BUILD);
    b.onclick = () => { inTranche ? S.picked.delete(d.id) : S.picked.add(d.id); render(); };
    c5.append(b);
  } else {
    // Fixable in place, without leaving the tranche you were building.
    const mayPrice = may(role, CAPS.PRICING);
    const b = el('button', 'mini', 'Add pricing');
    b.disabled = !mayPrice;
    b.title = mayPrice ? 'Add this rate to the investor matrix' : whyBlocked(role, CAPS.PRICING);
    b.onclick = () => addPricingModal(d, p.gap);
    c5.append(b);
  }
  tr.append(c5);

  return tr;
}

function renderSummary() {
  const rows = pickedRows();
  const t = trancheTotals(rows, S.adders);
  $('#sCount').textContent = t.count;
  $('#sIC').textContent = moneyK(t.investorContributionWithAdders);
  $('#sBosPct').textContent = pct(t.wBosPct);
  $('#sSowPct').textContent = pct(t.wSowPct);
  $('#sBos').textContent = money(t.bos);
  $('#sFee').textContent = money(t.financingFee);
  $('#sPrePay').textContent = money(t.grossPrepay);
  $('#sItc').textContent = money(t.itc);
  $('#sKw').textContent = `${t.kw.toFixed(1)} kW`;
}

function renderAdders() {
  const box = $('#adderLines');
  box.innerHTML = '';
  const mayEdit = may(actingRole(), CAPS.BUILD);

  S.adders.forEach((a, i) => {
    const row = el('div', 'line');
    row.append(el('span', '', a.label));
    const right = el('span', 'v');
    const inp = el('input');
    inp.type = 'number';
    inp.value = a.amount;
    inp.step = '1';
    inp.disabled = !mayEdit;
    inp.style.cssText = 'width:88px;text-align:right;font:inherit;border:0.5px solid var(--border);border-radius:4px;padding:2px 6px;';
    inp.onchange = (e) => { S.adders[i].amount = Number(e.target.value) || 0; render(); };
    right.append(inp);
    row.append(right);
    box.append(row);
  });

  const total = round2(S.adders.reduce((s, a) => s + (Number(a.amount) || 0), 0));
  $('#adderTotal').textContent = money(total);
  $('#addAdder').disabled = !mayEdit;
}

function renderWorking() {
  const rows = pickedRows();
  const box = $('#working');
  box.innerHTML = '';
  const mayBuild = may(actingRole(), CAPS.BUILD);

  if (!rows.length) {
    box.append(el('div', 'empty', 'No deals yet — add from the pool.'));
    return;
  }
  for (const r of rows.slice(0, 40)) {
    const row = el('div', 'wrow');
    const l = el('div');
    l.append(el('div', '', r.deal.Deal_Name.slice(0, 42)));
    l.append(el('div', 'dsub', `${r.deal.Account_Name ?? '—'} · ${r.deal.Customer_State}`));
    const rt = el('div', 'who-l');
    rt.append(el('span', 'amt', money(r.calc.bos)));
    const x = el('button', 'x', '✕');
    x.disabled = !mayBuild;
    x.onclick = () => { S.picked.delete(r.deal.id); render(); };
    rt.append(x);
    row.append(l, rt);
    box.append(row);
  }
  if (rows.length > 40) box.append(el('div', 'foot', `+ ${rows.length - 40} more`));
}

function renderActions() {
  const rows = pickedRows();
  const role = actingRole();
  const mayLock = may(role, CAPS.LOCK);

  // Lock applies to a CREATED tranche, not the working list — after Create the working
  // list is empty by design, so gating on it left Lock permanently disabled.
  const openTranches = sandbox.sandbox.tranches.filter((t) => t.status === 'Open');
  const lock = $('#lock');
  lock.disabled = !mayLock || !openTranches.length;
  lock.textContent = openTranches.length
    ? `Lock and generate documents (${openTranches.length})`
    : 'Lock and generate documents';
  const deny = $('#lockDeny');
  deny.textContent = mayLock ? '' : whyBlocked(role, CAPS.LOCK);
  deny.hidden = mayLock;

  // Create needs build rights AND sandbox mode; preview is read-only so it stays available.
  const mayBuild = may(role, CAPS.BUILD);
  $('#create').disabled = !mayBuild || !rows.length || !S.investorId;
  $('#create').title = mayBuild ? '' : whyBlocked(role, CAPS.BUILD);
  $('#preview').disabled = !rows.length;
  $('#status').className = `pill ${rows.length ? 'draft' : 'open'}`;
  $('#status').textContent = rows.length ? 'Draft' : 'Empty';

  const inv = investor();
  const gaps = inv ? pricingGaps(S.deals, inv) : [];
  const gbox = $('#gaps');
  gbox.innerHTML = '';
  if (gaps.length) {
    gbox.hidden = false;
    const blocked = gaps.reduce((s, g) => s + g.count, 0);
    gbox.append(el('div', 'sum-t', `Pricing gaps — ${blocked} deal${blocked > 1 ? 's' : ''} blocked, ${gaps.length} rubric${gaps.length > 1 ? 's' : ''}`));
    for (const g of gaps.slice(0, 5)) {
      const r = el('div', 'sum-row');
      const label = g.sow != null ? `${(g.sow * 100).toFixed(0)}% SOW · ${(g.tax * 100).toFixed(0)}% credit` : (g.state ?? '—');
      r.append(el('span', '', label), el('span', 'v', `${g.count} deal${g.count > 1 ? 's' : ''}`));
      gbox.append(r);
    }
    if (gaps.length > 5) gbox.append(el('div', 'sum-row', `+ ${gaps.length - 5} more — open Pricing matrix to fill them`));
  } else gbox.hidden = true;
}

function renderRecent() {
  const box = $('#recent');
  box.innerHTML = '';

  // Sandbox tranches first, visibly marked — they are the ones this session created.
  for (const t of sandbox.sandbox.tranches) {
    const c = el('div', 'rcard sbx');
    c.append(el('div', 'd', `${t.id} · ${String(t.createdAt).slice(0, 10)}`));
    c.append(el('div', 'n', `${t.investorName} · ${t.dealIds.length} deals`));
    const bb = el('div', 'b');
    bb.append(el('span', '', moneyK(t.totals?.investorContributionWithAdders ?? t.totals?.bos)));
    const st = el('span', '', t.status);
    st.style.color = t.status === 'Locked' ? 'var(--text-success)' : 'var(--text-warning)';
    bb.append(st);
    c.append(bb);
    if (t.documents?.length) {
      for (const d of t.documents) c.append(el('div', 'dsub', `✓ ${d.name} — ${d.status}`));
    }
    const acts = el('div', 'rcard-acts');
    const open = el('button', 'mini', 'Open');
    open.onclick = () => trancheDetailModal({ name: t.name, investor: t.investorName, date: String(t.createdAt).slice(0, 10), status: t.status, dealIds: t.dealIds, documents: t.documents });
    acts.append(open);
    // Swaps are a post-lock amendment — they only apply once the tranche is Locked (Trevor).
    if (t.status === 'Locked' && may(actingRole(), CAPS.SWAP) && t.dealIds.length) {
      const sw = el('button', 'mini', 'Swap a deal');
      sw.onclick = () => swapModal({ id: t.id, name: t.name, dealIds: t.dealIds, live: false });
      acts.append(sw);
    }
    const rm = el('button', 'mini', 'Discard');
    rm.onclick = () => { sandbox.deleteTranche(t.id); render(); };
    acts.append(rm);
    c.append(acts);
    box.append(c);
  }

  for (const t of S.recent) {
    // Did WE create this one this session? If so, offer a real undo / swap.
    const mine = sandbox.liveCreatedFor(t.id);
    const c = el('div', mine ? 'rcard mine' : 'rcard');
    c.append(el('div', 'd', t.date + (mine ? ' · created here' : '')));
    c.append(el('div', 'n', `${t.investor} · ${t.deals ?? mine?.dealIds.length ?? '—'} deals`));
    const b = el('div', 'b');
    b.append(el('span', '', moneyK(t.total)));
    const st = el('span', '', t.status);
    st.style.color = t.status === 'Locked' ? 'var(--text-success)' : 'var(--text-warning)';
    b.append(st);
    c.append(b);

    const acts = el('div', 'rcard-acts');
    const open = el('button', 'mini', 'Open');
    open.onclick = () => trancheDetailModal({ name: mine?.name ?? t.investor, investor: t.investor, date: t.date, status: t.status, dealIds: mine?.dealIds ?? null, dealCount: t.deals });
    acts.append(open);
    if (mine && may(actingRole(), CAPS.BUILD)) {
      // Post-lock only: swaps amend a locked (sold) tranche, not an open one.
      if (t.status === 'Locked' && may(actingRole(), CAPS.SWAP) && mine.dealIds?.length) {
        const sw = el('button', 'mini', 'Swap a deal');
        sw.onclick = () => swapModal({ id: t.id, name: mine.name ?? t.investor, dealIds: mine.dealIds, live: true });
        acts.append(sw);
      }
      const undo = el('button', 'mini', 'Undo (un-assign + delete)');
      undo.onclick = () => undoLive(t.id, undo);
      acts.append(undo);
    }
    c.append(acts);
    box.append(c);
  }
}

