function addPricingModal(deal, gap) {
  const inv = investor();
  if (!inv || !gap) return;

  openModal('Add pricing', (b) => {
    b.append(el('p', 'note', `${inv.Account_Name} has no rate for this deal's rubric. Add it here and every deal on the same rubric prices immediately.`));

    const rub = el('div', 'sum');
    for (const [k, v] of [
      ['Deal', deal.Deal_Name],
      ['Pre-pay % of SOW', pct(gap.sow)],
      ['Tax credit', pct(gap.tax) + (taxCreditFor(deal).ec || taxCreditFor(deal).dc ? `  (${tagsFor(deal).map((t) => t.label).join(' + ')})` : '')],
    ]) {
      const r = el('div', 'sum-row');
      r.append(el('span', '', k), el('span', 'v', String(v)));
      rub.append(r);
    }
    b.append(rub);

    const f = el('div', 'field');
    f.append(el('label', '', 'Bill-of-sale percentage for this rubric'));
    const input = el('input');
    input.type = 'number';
    input.step = '0.0001';
    input.placeholder = 'e.g. 0.6589';
    input.id = 'newRate';
    f.append(input);
    b.append(f);

    const preview = el('div', 'trace-holder');
    preview.append(el('p', 'note', 'Enter a rate to preview the full calculation.'));
    b.append(preview);

    const recalc = () => {
      const v = Number(input.value);
      preview.innerHTML = '';
      if (!Number.isFinite(v) || v <= 0 || v >= 1) {
        preview.append(el('p', 'note', 'Rate must be between 0 and 1 (e.g. 0.6589).'));
        return null;
      }
      preview.append(traceBlock(explainDeal(deal, { bosPct: v }).steps));
      return v;
    };
    input.oninput = recalc;

    const save = el('button', 'primary', 'Add rate and price the deal');
    save.onclick = () => {
      const v = recalc();
      if (v === null) { input.classList.add('bad'); return; }
      addRate(inv, gap.sow, gap.tax, v);
      S.picked.add(deal.id);   // he never leaves the flow — the deal joins the tranche
      closeModal();
      render();
    };
    b.append(save);

    // If this deal's rubric maps to one of CRM's five fixed rate cells and the investor is a
    // test account, offer to write it straight to CRM (the real thing, not just local).
    // Energy-Community specifically (the EC_/Non_EC_ column split), not the EC+DC tax total.
    const crmCol = columnForRubric(gap.sow, gap.tax, isEC(deal));
    if (isTestInvestor(inv) && crmCol) {
      const toCrm = el('button', 'primary', 'Add rate and save to CRM');
      toCrm.style.marginLeft = '8px';
      toCrm.title = `Writes ${crmCol.col} for ${deal.Customer_State} · ${productFor(deal)} to the investor’s CRM pricing record (test account).`;
      toCrm.onclick = async () => {
        const v = recalc();
        if (v === null) { input.classList.add('bad'); return; }
        toCrm.disabled = true; toCrm.textContent = 'Saving to CRM…';
        try {
          await saveRateToCrm(inv, deal.Customer_State, productFor(deal), crmCol.col, v);
          addRate(inv, gap.sow, gap.tax, v);   // keep the local matrix in step
          S.picked.add(deal.id);
          closeModal();
          render();
        } catch (e) {
          toCrm.disabled = false; toCrm.textContent = 'Save to CRM failed — retry';
          console.error('save rate to CRM failed', e);
        }
      };
      b.append(toCrm);
      b.append(el('p', 'note', `“Add rate” stores it locally for this session. “Save to CRM” writes cell ${crmCol.col} to ${inv.Account_Name}’s CRM pricing record (created on first save; test accounts only).`));
    } else if (isTestInvestor(inv)) {
      b.append(el('p', 'note', `This rubric (${pct(gap.sow)} SOW / ${pct(gap.tax)} credit) is not one of CRM’s five fixed rate cells, so it can only be stored locally — CRM’s matrix has no column for it. Use “Edit pricing in CRM” for the cells CRM can hold.`));
    } else {
      b.append(el('p', 'note', 'Saved to the local pricing matrix for this session. Writing to CRM is enabled for the two test investors only.'));
    }
  });
}

/** True for the two CRM accounts pricing may be written to. */
const isTestInvestor = (inv) => !!inv && TEST_INVESTOR_IDS.includes(String(inv.id));

/**
 * Write a Bill-of-Sale rate cell to CRM (live, in Zoho) or to the local preview (standalone),
 * then refresh so the value shows through immediately.
 */
async function saveRateToCrm(inv, state, product, column, value) {
  const live = isLive() && mode.isSandbox && PRICING_WRITES && isTestInvestor(inv);
  if (live) {
    await zohoSaveInvestorRateLive({ accountId: inv.id, state, product, column, value });
    inv.livePricing = undefined;          // force a re-read so the new cell appears
    await ensureInvestorPricing(inv);
  } else {
    sandbox.setCrmRate(inv.id, state, product, column, value);
  }
}

/**
 * Edit an investor's real CRM pricing cells — the five fixed Bill-of-Sale % cells, keyed by
 * State × Product. This is "add the missing rate to CRM": fill an empty cell (e.g. the
 * pending 50% tier) or a new State row, and it writes to the Investor_Pricing_Matrix subform
 * (the record is created on first save — the test accounts start with none). Test investors
 * only; sandbox only.
 */
function crmRateEditorModal(inv, preset = {}) {
  if (!inv) return;
  const states = [...new Set(S.deals.map((d) => d.Customer_State).filter(Boolean))].sort();
  if (!states.length) states.push('CA');
  let state = preset.state || states[0];
  let product = preset.product || 'PPA';

  const currentCell = (col) => {
    // Live: decode the loaded rates back to a column value. Standalone: the local preview.
    if (inv.livePricing?.found) {
      const spec = CRM_RATE_COLUMNS.find((c) => c.col === col);
      const hit = inv.livePricing.rates.find(
        (r) => r.state === state && r.product === product &&
          Math.abs(r.tax - spec.tax) < 1e-9 && r.ec === spec.ec &&
          (spec.sow == null || (r.sow != null && Math.abs(r.sow - spec.sow) < 5e-3))
      );
      if (hit) return hit.bosPct;
    }
    const local = sandbox.getCrmRate(inv.id, state, product)[col];
    return local ?? null;
  };

  openModal(`Edit pricing in CRM — ${inv.Account_Name}`, (b) => {
    const live = isLive() && mode.isSandbox && PRICING_WRITES;
    b.append(el('p', 'note',
      live
        ? 'Writes to the investor’s Investor_Pricing record in CRM (created on first save). CRM stores exactly five fixed rate cells per State × Product — fill any that are missing. Test accounts only.'
        : 'Preview of the CRM pricing editor. CRM stores exactly five fixed rate cells per State × Product. In the live widget this writes to the Investor_Pricing record; here it saves a local preview.'));

    const pickRow = el('div', 'crmrate-pick');
    const stSel = el('select');
    for (const s of states) { const o = el('option', '', s); o.value = s; if (s === state) o.selected = true; stSel.append(o); }
    stSel.onchange = (e) => { state = e.target.value; closeModal(); crmRateEditorModal(inv, { state, product }); };
    const prSel = el('select');
    for (const p of PRODUCTS) { const o = el('option', '', p); o.value = p; if (p === product) o.selected = true; prSel.append(o); }
    prSel.onchange = (e) => { product = e.target.value; closeModal(); crmRateEditorModal(inv, { state, product }); };
    const l1 = el('label', 'crmrate-lab', 'State'); l1.append(stSel);
    const l2 = el('label', 'crmrate-lab', 'Product'); l2.append(prSel);
    pickRow.append(l1, l2);
    b.append(pickRow);

    const status = el('p', 'note', '');

    for (const spec of CRM_RATE_COLUMNS) {
      const cur = currentCell(spec.col);
      const row = el('div', 'crmrate-row');
      const lab = el('div', 'crmrate-cellname');
      lab.append(el('span', '', spec.label));
      lab.append(el('span', 'dsub', spec.col));
      row.append(lab);
      const inp = el('input');
      inp.type = 'number'; inp.step = '0.0001'; inp.placeholder = 'unpriced';
      if (cur != null && cur > 0) inp.value = cur;
      inp.style.cssText = 'width:96px;text-align:right;font:inherit;border:0.5px solid var(--border);border-radius:4px;padding:3px 6px;';
      const save = el('button', 'mini', 'Save');
      save.onclick = async () => {
        const v = Number(inp.value);
        if (!Number.isFinite(v) || v <= 0 || v >= 1) { inp.classList.add('bad'); status.style.color = 'var(--text-danger)'; status.textContent = 'Rate must be between 0 and 1 (e.g. 0.655).'; return; }
        save.disabled = true; save.textContent = 'Saving…';
        try {
          await saveRateToCrm(inv, state, product, spec.col, v);
          status.style.color = 'var(--text-success)';
          status.textContent = `Saved ${spec.col} = ${(v * 100).toFixed(2)}% for ${state} · ${product}.`;
          save.textContent = 'Saved ✓';
          render();
        } catch (e) {
          save.disabled = false; save.textContent = 'Retry';
          status.style.color = 'var(--text-danger)';
          status.textContent = 'Save failed: ' + (e?.message || String(e));
        }
      };
      row.append(inp, save);
      b.append(row);
    }
    b.append(status);
  });
}

/** The investor pricing matrix — the half of Phase 1 that does not exist in CRM at all. */
/** Render an investor's REAL pricing read from the CRM Investor_Pricing module. */
function crmPricingView(p, b, inv) {
  const head = el('div', 'pricing-status');
  head.append(el('span', '', `From CRM — ${p.year || 'current'} pricing record · ${p.states.length} states × ${p.products.length} products · ${p.rates.length} priced cells.`));
  if (isTestInvestor(inv) && may(actingRole(), CAPS.PRICING)) {
    const edit = el('button', 'mini', 'Edit pricing in CRM');
    edit.onclick = () => { closeModal(); crmRateEditorModal(inv); };
    head.append(edit);
  }
  b.append(head);
  if (p.fees && (p.fees.corrient != null || p.fees.corrientEC != null)) {
    b.append(el('p', 'note', `Fees on the record: Corrient ${p.fees.corrient != null ? (p.fees.corrient * 100).toFixed(1) + '%' : '—'} · Corrient EC ${p.fees.corrientEC != null ? (p.fees.corrientEC * 100).toFixed(1) + '%' : '—'}.`));
  }
  b.append(el('p', 'note', 'Each cell is a Bill-of-Sale %, keyed by State + Product and (SOW/tax-credit). "pend/50" is the 50% tier — unpriced cells are a real gap and filter deals out.'));

  const tbl = el('table', 'atable');
  const head2 = el('tr');
  for (const h of ['State', 'Product', 'Rubric', 'Energy comm.', 'BoS %']) head2.append(el('th', '', h));
  tbl.append(head2);
  const sorted = [...p.rates].sort((a, c) =>
    a.state.localeCompare(c.state) || a.product.localeCompare(c.product) || a.tax - c.tax || (a.sow ?? 0) - (c.sow ?? 0)
  );
  for (const r of sorted) {
    const tr = el('tr');
    tr.append(
      el('td', '', r.state),
      el('td', '', r.product),
      el('td', '', `${r.sow != null ? (r.sow * 100).toFixed(0) : 'pend'}/${(r.tax * 100).toFixed(0)}`),
      el('td', '', r.ec ? 'EC' : '—'),
      el('td', '', (r.bosPct * 100).toFixed(2) + '%')
    );
    tbl.append(tr);
  }
  b.append(tbl);
  b.append(el('p', 'note', 'Read live from CRM (Investor_Pricing module). Product mapping from Deal Type is inferred — confirm with Gabe.'));
}

function pricingModal() {
  const inv = investor();
  if (!inv) return;
  const mayEdit = may(actingRole(), CAPS.PRICING);

  openModal(`Pricing — ${inv.Account_Name}`, (b) => {
    // Real CRM pricing when the investor has it; the local stopgap otherwise.
    if (inv.livePricing?.found) {
      crmPricingView(inv.livePricing, b, inv);
      return;
    }

    let rows = matrixFor(inv);
    const st = matrixStatus(inv);
    if (inv.livePricing && !inv.livePricing.found) {
      b.append(el('p', 'note', `No pricing record in CRM for ${inv.Account_Name} — using the local starter/entered matrix as a stopgap. Add an Investor_Pricing record in CRM and it will read through here.`));
    }

    // Test investors can create/fill their real CRM pricing straight from here — the five
    // fixed Bill-of-Sale cells per State × Product, written to Investor_Pricing.
    if (isTestInvestor(inv) && mayEdit) {
      const crmBar = el('div', 'pricing-status');
      crmBar.append(el('span', '', 'Save rates to CRM — the five fixed cells per State × Product (creates the record on first save).'));
      const edit = el('button', 'mini', 'Edit pricing in CRM');
      edit.onclick = () => { closeModal(); crmRateEditorModal(inv); };
      crmBar.append(edit);
      b.append(crmBar);
    }

    // Directly answers Gabe's "where is the pricing matrix for these dudes?": there is
    // none in CRM, so offer to seed one from Tranche 77 that he can then adjust.
    const bar = el('div', 'pricing-status');
    if (st.empty) {
      bar.append(el('span', '', `No pricing yet for ${inv.Account_Name}. There is no investor pricing matrix in CRM — this tool creates it.`));
    } else {
      bar.append(el('span', '', `${st.total} rates${st.starter ? ` · ${st.starter} starter (from Tranche 77)` : ''}${st.entered ? ` · ${st.entered} entered` : ''}.`));
    }
    if (mayEdit) {
      const load = el('button', 'mini', st.empty ? 'Load starter rates (Tranche 77)' : 'Reload starter rates');
      load.onclick = () => { loadStarterRates(inv); closeModal(); render(); pricingModal(); };
      bar.append(load);
    }
    b.append(bar);

    b.append(el('p', 'note', 'A rate is keyed on the deal’s pre-pay % of SOW and its tax-credit tier. Tax credit comes from the EC/DC rubric: 30% base, +10 energy community, +10 domestic content. Starter rates are the observed Tranche 77 values — adjust them per investor.'));

    const tbl = el('table', 'atable');
    const head = el('tr');
    head.append(el('th', '', 'Pre-pay % of SOW'));
    for (const t of TAX_TIERS) head.append(el('th', '', `${t.label} — ${t.rubric}`));
    tbl.append(head);

    const sows = [...new Set(rows.map((r) => r.sow))].sort((a, b2) => a - b2);
    for (const sow of sows) {
      const tr = el('tr');
      tr.append(el('td', '', pct(sow)));
      for (const t of TAX_TIERS) {
        const row = rows.find((r) => r.sow === sow && Math.abs(r.tax - t.value) < 1e-9);
        const td = el('td');
        if (!row) { td.append(el('span', 'dsub', '—')); tr.append(td); continue; }
        const inp = el('input');
        inp.type = 'number';
        inp.step = '0.0001';
        inp.value = row.bosPct;
        inp.disabled = !mayEdit;
        inp.style.cssText = 'width:86px;text-align:right;font:inherit;border:0.5px solid var(--border);border-radius:4px;padding:2px 5px;';
        inp.title = row.source === 'observed' ? 'From real Tranche 77 data' : row.source === 'entered' ? 'Entered here' : 'Modelled — not observed';
        if (row.source === 'modelled') inp.style.color = 'var(--text-muted)';
        inp.onchange = (e) => {
          const v = Number(e.target.value);
          if (Number.isFinite(v) && v > 0 && v < 1) {
            row.bosPct = v;
            row.source = 'entered';
            saveMatrix(inv, rows);
            render();
          }
        };
        td.append(inp);
        tr.append(td);
      }
      tbl.append(tr);
    }
    if (sows.length) b.append(tbl);

    const gaps = pricingGaps(S.deals, inv);
    if (gaps.length) {
      b.append(el('div', 'sum-t', `${gaps.length} rubric${gaps.length > 1 ? 's' : ''} in the current pools with no rate`));
      for (const g of gaps.slice(0, 10)) {
        const r = el('div', 'sum-row');
        r.append(el('span', '', `${pct(g.sow)} SOW at ${pct(g.tax)} tax credit`), el('span', 'v', `${g.count} deal${g.count > 1 ? 's' : ''}`));
        b.append(r);
      }
    }
    if (!mayEdit) b.append(el('p', 'deny', whyBlocked(actingRole(), CAPS.PRICING)));
  });
}

/** Create the tranche — sandbox only. Gabe: "create trunch, but, boom... shows everything". */
function createModal() {
  const rows = pickedRows();
  const inv = investor();
  if (!rows.length || !inv) return;
  const t = trancheTotals(rows, S.adders);

  openModal('Create tranche', (b) => {
    b.append(el('div', 'mono', `${inv.Account_Name} Tranche ${S.targetLock}`));
    b.append(el('p', 'note', 'Name follows automation.Untitled_Function2 — downstream CRM report filters depend on this exact shape.'));

    for (const [k, v] of [
      ['Deals', String(t.count)],
      ['Capacity', `${t.kw.toFixed(1)} kW`],
      ['Total gross prepay', money(t.prePay)],
      ['Total bill of sale', money(t.bos)],
      ['Total adders', money(t.adders)],
      ['Total investor contribution', money(t.investorContributionWithAdders)],
      ['Est. ITC', money(t.itc)],
    ]) {
      const r = el('div', 'sum-row');
      r.append(el('span', '', k), el('span', 'v', v));
      b.append(r);
    }

    if (t.unpriced) {
      const w = el('div', 'banner warn');
      w.textContent = `${t.unpriced} deal(s) in this tranche have no rate and are excluded from the totals. Add pricing before creating.`;
      b.append(w);
    }

    const holder = el('div', 'trace-holder');
    showMath(holder, explainTranche(rows, S.adders).steps);
    b.append(holder);

    // Real write only inside CRM, in sandbox, with the flag on — and createTrancheLive
    // still hard-refuses any non-test deal.
    const live = isLive() && mode.isSandbox && TRANCHE_CREATE_WRITES;
    const name = `${inv.Account_Name} Tranche ${S.targetLock}`;

    if (live) {
      const warn = el('div', 'banner info');
      warn.innerHTML =
        '<strong>This writes to CRM.</strong> It creates a real Tranche and assigns these ' +
        `${t.count} test deals to it. Test records only — it refuses anything else. Lock stays simulated.`;
      b.append(warn);
    } else {
      b.append(actionBlock(explainAction('create', { name, investorName: inv.Account_Name, dealCount: t.count })));
    }

    const go = el('button', 'primary', live ? 'Create tranche in CRM' : 'Create tranche (sandbox)');
    const status = el('p', 'note');
    go.onclick = async () => {
      if (live) {
        go.disabled = true;
        status.textContent = 'Creating tranche and assigning deals…';
        try {
          const res = await zohoCreateTrancheLive({
            name, investorId: inv.id, trancheDate: S.targetLock, deals: rows.map((r) => r.deal),
          });
          // Remember it so we can offer one-click undo (un-assign deals + delete tranche).
          if (res.trancheId) {
            sandbox.recordLiveCreate({
              trancheId: res.trancheId, name, dealIds: res.assigned,
              investorName: inv.Account_Name, createdAt: new Date().toISOString(),
            });
          }
          S.picked.clear();
          // Refresh from CRM: assigned deals drop out of the pools, the new tranche appears.
          S.deals = await loadDeals();
          S.recent = await loadRecentTranches();
          status.innerHTML =
            `<strong>Created.</strong> Tranche ${res.trancheId} · ${res.assigned.length} deals assigned` +
            (res.errors.length ? ` · ${res.errors.length} failed` : '') + '.';
          go.textContent = 'Done';
          setTimeout(() => { closeModal(); render(); }, 1400);
        } catch (e) {
          status.innerHTML = `<span style="color:var(--text-danger)"><strong>Write failed.</strong> ${e.message}</span>`;
          go.disabled = false;
        }
      } else {
        const rec = sandbox.createTranche({
          investor: inv, dealIds: rows.map((r) => r.deal.id), totals: t, adders: S.adders, targetLock: S.targetLock,
        });
        S.picked.clear();
        S.activeTranche = rec.id;
        closeModal();
        render();
      }
    };
    b.append(go, status);
    if (!live) b.append(el('p', 'note', 'Nothing is written to CRM. The tranche appears in Recent below and its deals leave the pool.'));
  });
}

async function marginModal() {
  // THE FIX: price every deal under every investor, so load EVERY investor's pricing first.
  // Previously only the selected investor was loaded, so on live data every other investor
  // was ruled ineligible and the comparison silently collapsed to a single column.
  await ensureAllInvestorPricing(S.investors);

  const pool = S.deals.filter((d) => poolFor(d) === 'available');
  const res = allocate(pool, S.investors, priceFor).sort(
    (a, c) => (c.marginGap ?? -Infinity) - (a.marginGap ?? -Infinity)
  );
  const pricedInvestors = S.investors.filter(
    (i) => i.livePricing?.found || (i.seedProfile || i.sample)
  ).length;

  openModal('Maximise margin — recommendation', (b) => {
    b.append(el('p', 'note', 'Prices every available deal under every investor and recommends whoever contributes most, showing the dollar cost of overriding (the gap to the runner-up). Sorted by that gap. It recommends only — Gabe’s rule; it never assigns.'));

    if (pricedInvestors < 2) {
      b.append(el('p', 'deny',
        `Only ${pricedInvestors} investor${pricedInvestors === 1 ? ' has' : 's have'} pricing loaded, so there is nothing to compare against yet. The comparison is meaningful once two or more investors are priced (in the sandbox both demo investors are; on live data it needs Investor_Pricing records for 2+ real investors).`));
    }

    const scroll = el('div', 'margin-scroll');
    const tbl = el('table', 'atable');
    const head = el('tr');
    for (const h of ['Deal', 'Recommended', 'Margin gap', 'Eligible']) head.append(el('th', '', h));
    tbl.append(head);
    for (const r of res) {
      const tr = el('tr');
      tr.append(el('td', '', r.deal.Deal_Name.slice(0, 34)));
      tr.append(el('td', '', r.recommended?.Account_Name?.replace(' (sample)', '').replace(' Demo', '') ?? '— none —'));
      tr.append(el('td', '', r.marginGap == null ? '—' : money(r.marginGap)));
      tr.append(el('td', '', `${r.eligibleCount}/${S.investors.length}`));
      tbl.append(tr);
    }
    scroll.append(tbl);
    b.append(scroll);
    b.append(el('p', 'note', `${res.length} deal${res.length === 1 ? '' : 's'} in the available pool. Every rubric must be priced for an investor to be a candidate — an unpriced investor is simply not eligible, shown in the Eligible count.`));

    // Human-in-the-loop, never-assign-safe action: pre-pick (into the working draft only)
    // the deals this comparison says the SELECTED investor wins. No CRM write; the human
    // still reviews the selection and hits Create.
    const inv = investor();
    if (inv && may(actingRole(), CAPS.BUILD)) {
      const wins = res.filter((r) => r.recommended?.id === inv.id).map((r) => r.deal);
      const pick = el('button', 'primary', `Select ${inv.Account_Name.replace(' Demo', '')}’s ${wins.length} winners`);
      pick.disabled = !wins.length;
      pick.title = 'Adds these deals to the working tranche selection. Nothing is written — you still review and Create.';
      pick.onclick = () => {
        for (const d of wins) S.picked.add(d.id);
        closeModal();
        render();
      };
      b.append(pick);
      b.append(el('p', 'note', 'That only fills the selection for the investor you have chosen — it does not create or assign anything. Review the working tranche, then Create as usual.'));
    }
  });
}

/* ------------------------------------------------------------------ boot */
async function boot() {
  // Identity first — but never let Zoho block the render. Outside CRM (local dev,
  // direct GitHub Pages hit) PageLoad simply never fires, so we time-box it.
  note({ framed: inZoho() });
  if (inZoho()) {
    try {
      await Promise.race([whenReady(), new Promise((r) => setTimeout(r, 10000))]);
      S.realUser = await currentUser();
      await orgInfo();
    } catch (e) {
      console.warn('Zoho init failed — continuing with sample data', e);
    }
  }
  S.realRole = roleForUser(S.realUser);

  // Nobody is signed in (standalone preview) ⇒ default the simulator to an admin so the
  // whole surface is explorable. Inside CRM the real user's own role governs.
  if (!S.realUser) S.viewAs = viewAsOptions()[0];

  const [deals, investors, recent, views] = await Promise.all([
    loadDeals(), loadInvestors(), loadRecentTranches(), loadPoolViews(),
  ]);
  S.deals = deals;
  S.investors = investors;
  S.recent = recent;
  S.poolViews = views;
  S.investorId = investors[0]?.id ?? null;
  // Load the selected investor's REAL CRM pricing (no-op outside CRM / if none exists).
  await ensureInvestorPricing(investor());

  const src = $('#srcBanner');
  if (isLive() && !fallback.active) {
    src.className = 'banner info';
    src.innerHTML = `<strong>Live CRM data.</strong> Reads are real; all writes are disabled in this build.`;
  } else if (fallback.active) {
    // The widget loaded fine — it's the data layer that didn't. Say which, because the
    // fixes are in different places (tab/URL config vs CRM permissions or COQL).
    src.className = 'banner warn';
    src.innerHTML =
      `<strong>Widget loaded, but live CRM reads failed — showing sample data.</strong> ` +
      `The embed and the UI are fine; the data call is what broke. Reason: ` +
      `<code>${String(fallback.reason).slice(0, 160)}</code>`;
  } else {
    src.className = 'banner warn';
    src.innerHTML =
      `<strong>Sample data.</strong> Economics are real — taken from Fairtide Fund III Series 1 LLC ` +
      `Tranche 77 (2026-07-14, 100 deals) and used to validate every formula. Customer and installer ` +
      `names are synthetic. Pool assignment is synthetic. Load inside CRM for live records.`;
  }

  $('#investor').onchange = async (e) => {
    S.investorId = e.target.value;
    S.picked.clear();
    // "which sets all the different fees, right? Like a default."
    S.adders = DEFAULT_FEES.map((f) => ({ ...f }));
    render(); // paint immediately with the stopgap…
    await ensureInvestorPricing(investor());
    render(); // …then re-paint if real CRM pricing loaded
  };
  $('#newTranche').onclick = () => {
    // Start a fresh draft: clear the working selection and adders, then take the user to the
    // builder and flash it so the action is visibly felt (empty→empty otherwise looks dead).
    S.picked.clear();
    S.adders.forEach((a) => (a.amount = 0));
    S.activeTranche = null;
    render();
    const builder = $('#builder');
    if (builder) {
      builder.scrollIntoView({ behavior: 'smooth', block: 'center' });
      builder.classList.remove('flash');
      void builder.offsetWidth;           // restart the animation if clicked repeatedly
      builder.classList.add('flash');
      setTimeout(() => builder.classList.remove('flash'), 900);
    }
  };
  $('#addAdder').onclick = () => {
    S.adders.push({ label: `Custom adder ${S.adders.length - 1}`, amount: 0 });
    render();
  };
  $('#preview').onclick = previewModal;
  $('#lock').onclick = lockModal;
  $('#margin').onclick = marginModal;
  $('#conn').onclick = connectionModal;
  $('#create').onclick = createModal;
  $('#pricing').onclick = pricingModal;
  $('#assume').onclick = assumptionsModal;

  $('#modalClose').onclick = closeModal;
  $('#modal').onclick = (e) => { if (e.target.id === 'modal') closeModal(); };

  render();
}

boot().catch((e) => {
  console.error(e);
  $('#app').innerHTML = `<div class="banner warn"><strong>Failed to start.</strong> ${e.message}</div>`;
});
